def solve(x=500.0, depth=1.0, width=1.0, U=1.0, D=0.01, sigma_1=32.0):
    # Time of travel to reach x
    t = x / U  # seconds

    # For a Gaussian tracer distribution, variance = 2 * K * t
    # sigma^2 = 2 * K_X1 * t  =>  K_X1 = sigma^2 / (2 * t)
    variance = sigma_1 ** 2
    K_X1 = variance / (2.0 * t)

    return {
        "1": {"value": K_X1, "unit": "m^2/s"}
    }

def solve(Q=4500.0, S0=150.0, S=7.0, sludge_age=10.0, MLVSS=1400.0, Y=0.60, ke=0.06):
    # F/M ratio derived from mean cell residence time relationship:
    # 1/theta_c = Y*(F/M)*E - ke   where E = (S0 - S)/S0 (substrate utilization efficiency)
    # Rearranged: F/M = (1/theta_c + ke) / (Y * E)

    E = (S0 - S) / S0  # fraction of substrate removed

    FM = (1.0 / sludge_age + ke) / (Y * E)

    return {
        "1": {"value": FM, "unit": "mg COD / mg VSS-day"}
    }

def solve(q=0.5, Q=4.5, B=10.0, h=2.0, D=0.05, Kx=0.5, L=2000.0):
    # Total flow after mixing
    Q_total = Q + q  # m^3/s

    # Cross-sectional area of river
    A = B * h  # m^2

    # Mean velocity in river
    u = Q_total / A  # m/s

    # Advection time scale for transport from culvert to x = L
    t = L / u  # s

    return {
        "1": {"value": t, "unit": "s"}
    }

