import math

def solve(C0=10.0, C_target=1.0, x_cm=50.0, D_cm2_s=1.0):
    # Step initial condition diffusion:
    # C(x,t) = (C0/2) * erfc( x / (2*sqrt(D*t)) )
    # Solve for t given C(x,t)=C_target.

    # erfc via math.erfc; need inverse erfc.
    ratio = C_target / (C0 / 2.0)  # = erfc(arg)
    # ratio must be in (0,2)

    # Find arg such that erfc(arg) = ratio  (arg > 0 since ratio < 1)
    def erfc(z):
        return math.erfc(z)

    # Bisection to invert erfc
    lo, hi = 0.0, 10.0
    for _ in range(200):
        mid = 0.5 * (lo + hi)
        if erfc(mid) > ratio:
            lo = mid
        else:
            hi = mid
    arg = 0.5 * (lo + hi)

    # arg = x / (2*sqrt(D*t))  ->  t = x^2 / (4 * D * arg^2)
    t_s = (x_cm ** 2) / (4.0 * D_cm2_s * arg ** 2)

    return {
        "1": {"value": t_s, "unit": "s"}
    }
